<div class="card mb-3"><div class="card-header">Información de la venta · <?=h($v['Estado'])?></div><div class="card-body"><div class="row g-3"><div class="col-md-4"><strong>Fecha:</strong> <?=h($v['Fecha'])?></div><div class="col-md-4"><strong>Cliente:</strong> <?=h($v['Cliente'])?></div><div class="col-md-4"><strong>Vendedor:</strong> <?=h($v['NombreCompleto'])?></div></div></div></div>
<div class="card mb-3"><div class="card-header">Productos vendidos</div><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Producto</th><th>Presentación</th><th>Cantidad</th><th>Precio</th><th>Subtotal</th><th>Descuento</th><th>Total</th><th>Devuelto</th></tr></thead><tbody>
<?php foreach($v['lineas'] as $l): ?><tr><td><strong><?=h($l['Producto'])?></strong><div class="small text-muted"><?=h($l['Codigo'])?></div></td><td><?=h($l['Presentacion'])?><div class="small"><?=h($l['UnidadesPorPresentacion'])?> <?=h($l['UnidadBase'])?> por presentación</div></td><td><?=h($l['Cantidad'])?></td><td class="text-nowrap"><?=dinero($l['Precio'])?></td><td class="text-nowrap"><?=dinero($l['Subtotal'])?></td><td class="text-nowrap"><?=dinero($l['Descuento'])?></td><td class="text-nowrap"><?=dinero($l['Total'])?></td><td><?=h($l['CantidadDevuelta'])?> / <?=h($l['Cantidad'])?><div class="small text-nowrap"><?=dinero($l['ImporteDevuelto'])?></div></td></tr><?php endforeach; ?></tbody></table></div>
<div class="row g-3 resumen-venta"><div class="col-6 col-lg-3">Total original<strong class="d-block"><?=dinero($v['Total'])?></strong></div><div class="col-6 col-lg-3">Efectivo recibido<strong class="d-block"><?=dinero($v['Efectivo'])?></strong></div><div class="col-6 col-lg-3">Cambio entregado<strong class="d-block"><?=dinero($v['Cambio'])?></strong></div><div class="col-6 col-lg-3">Reintegrado al cliente<strong class="d-block"><?=dinero($v['Reintegrado'])?></strong></div></div><p class="mt-3 mb-0">Venta neta después de devoluciones: <strong><?=dinero(decimalImporte(centavos($v['Total'])-centavos($v['Reintegrado'])))?></strong></p></div></div>
<div class="card mb-3"><div class="card-header">Trazabilidad de lotes</div><div class="card-body"><p class="small text-muted">Las cantidades siguientes están en unidades base. Una presentación puede salir de varios lotes.</p><div class="table-responsive"><table class="table"><thead><tr><th>Producto</th><th>Lote</th><th>Vencimiento</th><th>Unidades vendidas</th><th>Unidades reintegradas</th></tr></thead><tbody><?php foreach($v['lotes'] as $a): $l=current(array_filter($v['lineas'],fn($x)=>(int)$x['DetalleID']===(int)$a['DetalleID'])); ?><tr><td><?=h($l['Producto'])?></td><td><?=h($a['NumeroLote'])?></td><td><?=h($a['FechaVencimiento'])?></td><td><?=h($a['Unidades'])?></td><td><?=h($a['UnidadesDevueltas'])?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<div class="card mb-3"><div class="card-header">Devoluciones y anulaciones</div><div class="card-body"><?php if(!$v['devoluciones']): ?><p class="text-muted mb-0">Esta venta no tiene devoluciones ni anulaciones.</p><?php endif; ?>
<?php foreach($v['devoluciones'] as $r): ?><article class="border rounded p-3 mb-3"><div class="d-flex justify-content-between flex-wrap gap-2"><strong><?=h($r['Tipo']==='Anulacion'?'Anulación':'Devolución')?> #<?=h($r['DevolucionID'])?></strong><strong>Reintegro en efectivo: <?=dinero($r['Total'])?></strong></div><div class="small text-muted"><?=h($r['Fecha'])?> · <?=h($r['NombreCompleto'])?></div><p class="motivo-venta mt-2 mb-2"><?=h($r['Motivo'])?></p>
<?php $s=$db->prepare('SELECT d.Producto,d.Presentacion,r.Cantidad,r.Unidades,r.Importe FROM DevolucionVentaDetalle r JOIN VentaDetalle d ON d.DetalleID=r.DetalleID WHERE r.DevolucionID=? ORDER BY r.ReintegroID');$s->execute([$r['DevolucionID']]);foreach($s->fetchAll(PDO::FETCH_ASSOC) as $d): ?><div><?=h($d['Producto'])?> · <?=h($d['Cantidad'])?> <?=h($d['Presentacion'])?> · <?=h($d['Unidades'])?> unidades base · <?=dinero($d['Importe'])?></div><?php endforeach; ?>
<?php $s=$db->prepare('SELECT l.NumeroLote,SUM(t.Unidades) AS Unidades FROM DevolucionVentaLotes t JOIN DevolucionVentaDetalle rd ON rd.ReintegroID=t.ReintegroID JOIN VentaLotes a ON a.AsignacionID=t.AsignacionID JOIN LotesMedicamentos l ON l.LoteID=a.LoteID WHERE rd.DevolucionID=? GROUP BY l.LoteID,l.NumeroLote ORDER BY l.LoteID');$s->execute([$r['DevolucionID']]);foreach($s->fetchAll(PDO::FETCH_ASSOC) as $lote): ?><div class="small text-muted">Retorno a lote <?=h($lote['NumeroLote'])?>: <?=h($lote['Unidades'])?> unidades base</div><?php endforeach; ?></article><?php endforeach; ?></div></div></div>
<span id="venta-registrada" hidden data-usuario="<?=h($_SESSION['usuario_id'])?>" data-operacion="<?=h($v['ClaveOperacion'])?>"></span><script src="/clinica/js/ventas_resultado.js?v=4"></script>
